{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "Brexpiprazole, the closest analogue sharing the dihydroquinolinone/butoxyarylpiperazine scaffold, has an absolute oral bioavailability of 95% in humans, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Ziprasidone, another arylpiperazine antipsychotic with a chloro-substituted fused heterocycle, has an absolute oral bioavailability of about 59-60% in healthy subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Urapidil, an arylpiperazine with a similar ether/piperazine linker, shows an absolute oral bioavailability of 78% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Trazodone, an arylpiperazine antidepressant, has an absolute oral bioavailability of approximately 80%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Flibanserin, a benzimidazolone arylpiperazine, has an absolute oral bioavailability of about 46%, still well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Prochlorperazine, a phenothiazine with low oral bioavailability (~12.5%), is structurally distant from the query and does not override the high-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is aripiprazole-like, with a dihydroquinolinone core and a 4-(4-(2,3-dichlorophenyl)piperazin-1-yl)butoxy side chain. The closest analogue brexpiprazole has 95% absolute oral bioavailability in humans, and several other arylpiperazine drugs show F values of 46-80%, all well above the 20% threshold. Low-F comparators are structurally distant phenothiazine or benzoquinolizine compounds. Therefore, F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the supplied evidence; the prediction relies on close analogues.",
    "Formulation and food effects are not systematically captured for the query, though the high-F analogues were measured under relevant oral dosing conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

